import { execFile } from "node:child_process";
import path from "node:path";
import { promisify } from "node:util";
import { UsageError } from "../core/errors.js";
import type { ConfigWarning, DependencyReference } from "../core/types.js";
import { isSupportedDependencyFile, parseDependencyFile } from "../parsers/index.js";
import { toPosixPath } from "../parsers/common.js";
import {
  discoverDependencyFiles,
  isIgnoredPath,
  parseWorkspaceFiles
} from "./find-files.js";

const execFileAsync = promisify(execFile);

export async function parseChangedDependencyReferences(input: {
  rootDir: string;
  baseRef?: string;
}): Promise<{
  references: DependencyReference[];
  warnings: ConfigWarning[];
}> {
  if (!(await isGitRepository(input.rootDir))) {
    throw new UsageError("--changed-only requires a git repository.");
  }

  const baseRef = input.baseRef ?? (await getDefaultBaseRef(input.rootDir));

  const mergeBase = await getMergeBase(input.rootDir, baseRef);
  const changedFiles = await getChangedSupportedFiles(input.rootDir, mergeBase);

  if (changedFiles.length === 0) {
    return { references: [], warnings: [] };
  }

  const head = await parseWorkspaceFiles({
    rootDir: input.rootDir,
    files: changedFiles
  });
  const base = await parseBaseFiles({
    rootDir: input.rootDir,
    baseRef: mergeBase,
    files: changedFiles
  });

  return {
    references: diffDependencyReferences(base.references, head.references),
    warnings: [...head.warnings, ...base.warnings]
  };
}

function diffDependencyReferences(
  baseReferences: readonly DependencyReference[],
  headReferences: readonly DependencyReference[]
): DependencyReference[] {
  const basePackages = new Set(baseReferences.map(referenceKey));
  return headReferences.filter((reference) => !basePackages.has(referenceKey(reference)));
}

function referenceKey(reference: DependencyReference): string {
  return `${reference.ecosystem}:${reference.name}`;
}

async function parseBaseFiles(input: {
  rootDir: string;
  baseRef: string;
  files: readonly string[];
}): Promise<{
  references: DependencyReference[];
  warnings: ConfigWarning[];
}> {
  const references: DependencyReference[] = [];
  const warnings: ConfigWarning[] = [];
  const pendingFiles = [...new Set(input.files)];
  const parsedFiles = new Set<string>();
  const includedRequirementFiles = new Set<string>();

  while (pendingFiles.length > 0) {
    const file = pendingFiles.shift();
    if (file === undefined || parsedFiles.has(file)) {
      continue;
    }
    parsedFiles.add(file);

    const content = await readGitFile(input.rootDir, input.baseRef, file);
    if (content === undefined) {
      continue;
    }

    const parsed = parseDependencyFile({
      sourceFile: file,
      content,
      ...(includedRequirementFiles.has(file)
        ? { format: "python-requirements" }
        : {})
    });
    references.push(...parsed.references);
    warnings.push(...parsed.warnings);

    for (const includedFile of parsed.includedFiles ?? []) {
      const resolvedFile = resolveIncludedFile({
        rootDir: input.rootDir,
        sourceFile: file,
        includedFile
      });

      if (resolvedFile === undefined) {
        warnings.push({
          file,
          message: `Skipped requirement include outside scan root: ${includedFile}.`
        });
        continue;
      }

      if (!parsedFiles.has(resolvedFile)) {
        includedRequirementFiles.add(resolvedFile);
        pendingFiles.push(resolvedFile);
      }
    }
  }

  return { references, warnings };
}

function resolveIncludedFile(input: {
  rootDir: string;
  sourceFile: string;
  includedFile: string;
}): string | undefined {
  if (path.isAbsolute(input.includedFile)) {
    return undefined;
  }

  const absoluteFile = path.resolve(
    input.rootDir,
    path.dirname(input.sourceFile),
    input.includedFile
  );
  const relativeFile = toPosixPath(path.relative(input.rootDir, absoluteFile));

  return relativeFile.startsWith("../") || relativeFile === ".."
    ? undefined
    : relativeFile;
}

async function isGitRepository(rootDir: string): Promise<boolean> {
  try {
    await execGit(rootDir, ["rev-parse", "--is-inside-work-tree"]);
    return true;
  } catch {
    return false;
  }
}

async function getDefaultBaseRef(rootDir: string): Promise<string> {
  try {
    const ref = await execGit(rootDir, ["symbolic-ref", "--short", "refs/remotes/origin/HEAD"]);
    return ref.trim() || "origin/main";
  } catch {
    return "origin/main";
  }
}

async function getMergeBase(rootDir: string, baseRef: string): Promise<string> {
  try {
    const output = await execGit(rootDir, ["merge-base", baseRef, "HEAD"]);
    return output.trim();
  } catch {
    return baseRef;
  }
}

async function getChangedSupportedFiles(
  rootDir: string,
  baseRef: string
): Promise<string[]> {
  try {
    const output = await execGit(rootDir, [
      "diff",
      "--name-only",
      "--diff-filter=AMRT",
      `${baseRef}...HEAD`
    ]);

    return output
      .split(/\r?\n/u)
      .map((file) => file.trim())
      .filter(
        (file) =>
          file.length > 0 && !isIgnoredPath(file) && isSupportedDependencyFile(file)
      )
      .sort();
  } catch {
    const files = await discoverDependencyFiles(rootDir);
    if (files.length === 0) {
      return [];
    }

    throw new UsageError(`Unable to compute changed files against ${baseRef}.`, {
      code: "cannot_compute_diff",
      hint: "Pass --base, fetch git history with actions/checkout fetch-depth: 0, or run a full scan."
    });
  }
}

async function readGitFile(
  rootDir: string,
  ref: string,
  file: string
): Promise<string | undefined> {
  try {
    return await execGit(rootDir, ["show", `${ref}:${file}`]);
  } catch {
    return undefined;
  }
}

async function execGit(rootDir: string, args: readonly string[]): Promise<string> {
  const { stdout } = await execFileAsync("git", [...args], {
    cwd: rootDir,
    maxBuffer: 10 * 1024 * 1024
  });
  return stdout;
}
